import 'package:lpinyin/lpinyin.dart';

void main() {
  String text = '天府广场';

  // Get short Pinyin (initials)
  String initials = PinyinHelper.getShortPinyin(text); // tfgc

  // Convert to Pinyin without tones
  String pinyin = PinyinHelper.getPinyinE(
    text,
    separator: ' ',
    format: PinyinFormat.WITHOUT_TONE,
  ); // tian fu guang chang
}
